/**
 * The contract with the Flexprice API.
 *
 * `@flexprice/sdk` is that contract — generated by Speakeasy from the backend's
 * OpenAPI document, the same document the Go and Python SDKs come from. This
 * package adds only what a browser needs and the SDK cannot know: how to prove
 * who the user is, and one error shape for everything that can fail.
 *
 * It deliberately does not re-model the API. The 53 hand-written DTO files and
 * 47 API classes in the V1 dashboard are what this replaces; adding a type here
 * that the SDK already has recreates the drift this package exists to end.
 *
 * Off-limits to components — import from `@fp/query`. ESLint enforces it.
 */
export { call, createFlexpriceClient } from './client'
export type { AuthSource, CallOptions, ClientOptions } from './client'
export { DEFAULT_REQUEST_TIMEOUT_MS } from './timeout'

export {
  ApiError,
  ErrorKind,
  kindForStatus,
  parseRetryAfter,
  readErrorBody,
  serverReason,
  toApiError,
} from './errors'

/**
 * Session bootstrap — the four routes missing from the OpenAPI document, and
 * therefore from the SDK. See `session.ts` for why they are here and what
 * deletes them.
 */
